INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Netzabdeckung immer von der Hardware allein abhängt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Umgebungsfaktoren"}, {"text": "Ja", "correct": false, "because": "Zu vereinfacht"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich die Netzabdeckung für ein IT-System plane?', 3, '[{"text": "Signalstärke", "correct": true, "because": "Sichert Verbindung"}, {"text": "Schnellste Installation", "correct": false, "because": "Qualität zählt"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Netzabdeckung?', 5, '[{"text": "Signalreichweite", "correct": true, "because": "Bestimmt Abdeckung"}, {"text": "Störquellen", "correct": true, "because": "Beeinträchtigen Signal"}, {"text": "Büromöbel", "correct": false, "because": "Kein Faktor"}, {"text": "Farbanalyse", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Netzabdeckung wird durch Access Points verbessert. b) Sie ist immer gleichmäßig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ungleichmäßig möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich die Netzabdeckung für ein IT-System plane?', 4, '[{"text": "Signalstärke", "correct": false, "because": "Sichert Verbindung"}, {"text": "Störquellen", "correct": false, "because": "Beeinträchtigen Signal"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Netzabdeckung nur für WLAN relevant ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Mobilfunk"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer guten Netzabdeckung?', 3, '[{"text": "Zuverlässige Verbindung", "correct": true, "because": "Sichert Kommunikation"}, {"text": "Schnellste Installation", "correct": false, "because": "Qualität zählt"}, {"text": "Weniger Reichweite", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind für die Netzabdeckung entscheidend?', 5, '[{"text": "Access Points", "correct": true, "because": "Erweitern Reichweite"}, {"text": "Antennen", "correct": true, "because": "Verstärken Signal"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Netzabdeckung hängt von der Signalstärke ab. b) Sie ist immer gleichmäßig verteilt. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ungleichmäßig möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um die Netzabdeckung in einem IT-System zu verbessern?', 4, '[{"text": "Signalverstärker", "correct": false, "because": "Erhöht Reichweite"}, {"text": "Netzwerkplanung", "correct": false, "because": "Sichert Abdeckung"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Netzabdeckung immer von der Hardware allein abhängig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Umgebung zählt"}, {"text": "Ja", "correct": false, "because": "Zu vereinfacht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gute Netzabdeckung?', 4, '[{"text": "Stabile Verbindung", "correct": true, "because": "Fördert Zuverlässigkeit"}, {"text": "Bessere Datenrate", "correct": true, "because": "Verbessert Leistung"}, {"text": "Schnellere Projekte", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Netzabdeckung nur für große Netzwerke wichtig ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Netzwerke"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
